-- V26__ui_text_catalog.sql
-- Каталог надписей интерфейса: что это за надпись, где она живёт
-- и как звучит на каждом языке.
--
-- Признак «где используется» принадлежит самой надписи, а не переводу:
-- он одинаков на всех языках. Поэтому ключи и значения разведены
-- по двум таблицам — иначе признак повторялся бы столько раз, сколько
-- языков, и копии со временем разошлись бы.
SET search_path = dbo;

CREATE TABLE IF NOT EXISTS ui_text_key (
  text_key  varchar(80) PRIMARY KEY,
  scope     varchar(20) NOT NULL,
  element   varchar(16) NOT NULL,
  owner     varchar(40),
  note      varchar(255)
);
COMMENT ON TABLE  ui_text_key IS 'Надписи интерфейса: ключ, раздел и вид объекта';
COMMENT ON COLUMN ui_text_key.scope   IS 'Раздел портала, где используется надпись';
COMMENT ON COLUMN ui_text_key.element IS 'Вид объекта: column, button, label, option, title, message, placeholder, hint, text';
COMMENT ON COLUMN ui_text_key.owner   IS 'К чему относится: имя таблицы для колонок, класс для сообщений сервера';
GRANT SELECT, INSERT, UPDATE, DELETE ON ui_text_key TO portal_app;

-- Старые ключи вида t0..t275 были машинными номерами из вёрстки: по ним
-- не понять, что за надпись и где она. Значения не переносим, а заводим
-- заново под осмысленными ключами — те же тексты идут ниже одним списком,
-- вместе с английскими. Перенос был бы и не нужен, и опасен: несколько
-- старых номеров приходились на один текст («Все» встречалось трижды),
-- и после переименования на один ключ пришлось бы два значения.
DELETE FROM ui_text WHERE text_key ~ '^t[0-9]+$';

