  ('receipts.label.expected_delivery_date', (SELECT locale_id FROM dictionary_locale WHERE code='ru'), 'Ожидаемая дата поставки'),
  ('receipts.label.expected_delivery_date', (SELECT locale_id FROM dictionary_locale WHERE code='en'), 'Expected delivery date'),
  ('common.label.driver_full_name', (SELECT locale_id FROM dictionary_locale WHERE code='ru'), 'ФИО водителя'),
  ('common.label.driver_full_name', (SELECT locale_id FROM dictionary_locale WHERE code='en'), 'Driver full name')
ON CONFLICT (text_key, locale_id) DO UPDATE SET value = excluded.value;

-- Теперь каждое значение обязано ссылаться на известный ключ: надпись,
-- которой нет в каталоге, негде показать, и такой перевод только мешает.
DELETE FROM ui_text WHERE text_key NOT IN (SELECT text_key FROM ui_text_key);
ALTER TABLE ui_text DROP CONSTRAINT IF EXISTS fk_ui_text_key;
ALTER TABLE ui_text ADD CONSTRAINT fk_ui_text_key
  FOREIGN KEY (text_key) REFERENCES ui_text_key (text_key) ON DELETE CASCADE;

-- Таблица для экрана ведения переводов: ключ, признаки и значения по языкам.
-- CREATE OR REPLACE не умеет менять набор возвращаемых колонок — пересоздаём.
DROP FUNCTION IF EXISTS ui_text_matrix();
CREATE FUNCTION ui_text_matrix()
RETURNS TABLE (text_key varchar, scope varchar, element varchar, owner varchar,
               locale_code varchar, value text)
LANGUAGE sql STABLE SET search_path = dbo AS $$
  SELECT k.text_key, k.scope, k.element, k.owner, l.code, t.value
    FROM ui_text_key k
   CROSS JOIN dictionary_locale l
    LEFT JOIN ui_text t ON t.text_key = k.text_key AND t.locale_id = l.locale_id
   WHERE l.is_active
   ORDER BY k.scope, k.element, k.text_key, l.sort_order
$$;
GRANT EXECUTE ON FUNCTION ui_text_matrix() TO portal_app;

-- Заводить ключи из администрирования не предусмотрено: они приходят
-- из вёрстки вместе с кодом. Запись перевода остаётся прежней (ui_text_save).
